from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    # Valid
    try:
        ServerSentEvent(event="foo", id="123", data="bar")
        print("Valid event passed")
    except Exception as e:
        print(f"Valid event failed: {e}")

    # Invalid event - newline
    try:
        ServerSentEvent(event="foo\nbar")
        print("Invalid event (newline) passed")
    except (ValueError, ValidationError) as e:
        print(f"Invalid event (newline) failed as expected: {e}")

    # Invalid event - carriage return
    try:
        ServerSentEvent(event="foo\rbar")
        print("Invalid event (CR) passed")
    except (ValueError, ValidationError) as e:
        print(f"Invalid event (CR) failed as expected: {e}")

    # Invalid id - newline
    try:
        ServerSentEvent(id="foo\nbar")
        print("Invalid id (newline) passed")
    except (ValueError, ValidationError) as e:
        print(f"Invalid id (newline) failed as expected: {e}")

    # Invalid id - carriage return
    try:
        ServerSentEvent(id="foo\rbar")
        print("Invalid id (CR) passed")
    except (ValueError, ValidationError) as e:
        print(f"Invalid id (CR) failed as expected: {e}")

    # Invalid id - null char
    try:
        ServerSentEvent(id="foo\0bar")
        print("Invalid id (null) passed")
    except (ValueError, ValidationError) as e:
        print(f"Invalid id (null) failed as expected: {e}")

test_sse_validation()
PY
